'use strict';

// MODULES //

var path = require( 'node:path' );
var readdir = require( 'node:fs/promises' ).readdir;


// MAIN //

/**
* Recursively lists regular files beneath a directory.
*
* @param {string} directory - directory path
* @param {string} [prefix] - relative prefix
* @returns {Promise<Array>} sorted relative paths
*/
async function walkFiles( directory, prefix ) {
	var files = [];
	var relative;
	var absolute;
	var entry;

	prefix = prefix || '';
	for ( entry of await readdir( directory, { 'withFileTypes': true } ) ) {
		relative = prefix ? prefix + '/' + entry.name : entry.name;
		absolute = path.join( directory, entry.name );

		if ( entry.isDirectory() ) {
			files.push.apply( files, await walkFiles( absolute, relative ) );
		} else if ( entry.isFile() ) {
			files.push( relative );
		} else {
			throw new Error( 'Unexpected non-file output entry: ' + relative );
		}
	}
	return files.sort();
}


// EXPORTS //

module.exports = walkFiles;
